  ui_story_30540401_92_dialog_content = "Nah, no estoy molesto contigo.",
  ui_story_30540601_1_dialog_content = "Estoy de vuelta...",
  ui_story_30540601_2_dialog_content = "\"¡Amo trabajar, sí lo hago!\"",
  ui_story_30540601_3_dialog_content = "\"Me encanta trabajar. ¿Y a ti?\"",
