  ui_story_30540601_11_dialog_content = "\"Trabajar\"? ¿Por qué ustedes siguen hablando de \"trabajar\"...",
  ui_story_30540601_12_dialog_content = "Bueno en realidad...",
  ui_story_30540601_13_dialog_content = "Un uniforme bien ajustado y bien planchado, y una taza de café humeante. Un comienzo perfecto para un duro día de trabajo—",
