  ui_story_30540601_17_dialog_content = "Pero de repente tener un día libre sin nada que hacer... Se siente un poco extraño para mí.",
  ui_story_30540601_18_dialog_content = "Eres tan trabajador y dedicado, Nadine! ¡Y también amas tu trabajo!",
  ui_story_30540601_19_dialog_content = "Si tan sólo...",
  ui_story_30540601_20_dialog_content = "¿Mmm? ¿Hay algo en tu mente, Vice?",
  ui_story_30540601_21_dialog_content = "Jeje... Solo estaba pensando... Si pudieras echarme una mano con algo, ¡estaría realmente agradecido!",
  ui_story_30540601_22_dialog_content = "¿Qué es? Siempre estoy dispuesto a ayudar, siempre y cuando esté dentro de mi capacidad hacerlo.",
  ui_story_30540601_23_dialog_content = "¿En serio?",
  ui_story_30540601_24_dialog_content = "Bueno, verás... Acabo de recibir una solicitud de misión urgente y no tengo más opción que irme de inmediato.",
  ui_story_30540601_25_dialog_content = "Pero hoy es mi turno de patrullar y PlayerName aún no ha regresado...",
  ui_story_30540601_26_dialog_content = "Entonces, ¿podrías ayudarme a manejar el Coloso, por favor?",
  ui_story_30540601_27_dialog_content = "Si tienes alguna pregunta, he creado este \"manual de servicio de patrulla\" al que puedes consultar cuando quieras.",
  ui_story_30540601_28_dialog_content = "Ya veo... Entendido. Déjamelo a mí y cuídate en tu misión.",
  ui_story_30540601_29_dialog_content = "¡Eres el mejor! ¡Muchas gracias!",
  ui_story_30540601_30_dialog_content = "Oh, y alguien entregará un paquete pronto. ¿Podrías recordar recibirlo, por favor?",
  ui_story_30540601_31_dialog_content = "Es un envío de ropa nueva.",
  ui_story_30540601_32_dialog_content = "Uno de ellos es una sorpresa para ti de PlayerName, así que eres más que bienvenido a abrirlo y echar un vistazo.",
  ui_story_30540601_33_dialog_content = "De todos modos, ¡debo irme! ¡El Colossus está en tus manos ahora!",
  ui_story_30540601_34_dialog_content = "Déjamelo a mí. ¡Haré lo mejor que pueda!",
  ui_story_30540601_35_dialog_content = "Hmm... El manual dice que las Luciérnagas se encargan de la mayoría de la limpieza en el Colossus. En ese caso...",
  ui_story_30540601_35X_dialog_content = "Quizás debería tomar una taza de café para animarme un poco, ¿no?",
  ui_story_30540601_36_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_30540601_38_dialog_content = "No presté atención cuando esa luciérnaga pasó volando junto a mí, así que me resbalé y caí...",
  ui_story_30540601_39_dialog_content = "Y derramé café por todo mi cuerpo. No tuve más opción que cambiarme a este atuendo.",
  ui_story_30540601_40_dialog_content = "Es tan bonito... ¡Juro que no ensuciaré este! ¿De verdad puedo ponérmelo, aunque?",
  ui_story_30540601_41_dialog_content = "Por supuesto que puedes. De todos modos, estaba planeando dártelo como un regalo.",
  ui_story_30540601_42_dialog_content = "¡Maravilloso!",
  ui_story_30540601_43_dialog_content = "De todos modos, ¿qué pasa con las luciérnagas? Estaban cantando y bailando hace un momento...",
  ui_story_30540601_44_dialog_content = "Ajusté sus configuraciones según el manual que Vice me dejó.",
  ui_story_30540601_45_dialog_content = "Lo que acabas de ver fue su formación en espera.",
  ui_story_30540601_46_dialog_content = "Y esa canción rara...",
  ui_story_30540601_47_dialog_content = "Lo canto para mí todo el tiempo. ¡Ojalá motive a nuestros amigos a hacer un trabajo aún mejor en el Coloso!",
  ui_story_30540601_48_dialog_content = "Ugh, ¿por qué sigues mencionando \"trabajo\" y \"empleos\"...",
  ui_story_30540601_49_dialog_content = "¡Oh, es cierto! ¡Todavía necesito terminar de inspeccionar las habitaciones!",
  ui_story_30540601_50_dialog_content = "¿Inspeccionando?",
  ui_story_30540601_51_dialog_content = "¡Oh, sirvienta!",
  ui_story_30540601_52_dialog_content = "Entendido.",
  ui_story_30540601_53_dialog_content = "Cambio de modos: Barredora.",
  ui_story_30540601_54_dialog_content = "Inspecciones de habitaciones completas. El contrabando ha sido confiscado.",
  ui_story_30540601_55_dialog_content = "C...¿Contrabando?",
  ui_story_30540601_56_dialog_content = "¡Así es! El manual de patrulla de Vice tiene varias reglas a seguir.",
  ui_story_30540601_57_dialog_content = "\"Para garantizar la seguridad de todos los pasajeros a bordo del Colossus, los siguientes objetos no están permitidos a bordo:\"",
  ui_story_30540601_58_dialog_content = "\"Inflamables o explosivos...\"",
  ui_story_30540601_59_dialog_content = "De repente, no puedo evitar pensar en todas las personas que rompen esta regla regularmente.",
  ui_story_30540601_60_dialog_content = "\"Armas peligrosas y objetos afilados...\"",
  ui_story_30540601_61_dialog_content = "De nuevo, no puedo evitar pensar en todas las personas que rompen esta regla regularmente, tampoco...",
  ui_story_30540601_62_dialog_content = "¿Ves? ¡Solo he terminado de leer la segunda regla y probablemente puedas nombrar a una docena de infractores!",
  ui_story_30540601_63_dialog_content = "No hay respeto entre las personas si no hay respeto por las reglas, ¿sabes?",
