  ui_story_30540601_65_dialog_content = "¡Sirvienta! ¡Vamonos!",
  ui_story_30540601_66_dialog_content = "Debería decirte que incluso Vice no aplica estas reglas muy estrictamente...",
  ui_story_30540601_66X_dialog_content = "Eh... ¿Hola? ¿Dónde fue?",
  ui_story_30540601_67_dialog_content = "<color=#e8d9bb>Diez minutos tarde...</color>",
  ui_story_30540601_68_dialog_content = "¿Dónde están mis altavoces? ¿Alguien los movió sin mi permiso?",
  ui_story_30540601_69_dialog_content = "¿Adónde se fue mi sierra pequeña y linda?",
  ui_story_30540601_70_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_30540601_71_dialog_content = "Regina... ¿Fuiste tú quien tomó mi sierra?",
  ui_story_30540601_72_dialog_content = "¿De qué estás balbuceando? Tú eres el que robó mis altavoces, ¿no?",
  ui_story_30540601_73_dialog_content = "¿Celoso de que sean incluso más altos que tú o algo así?!",
  ui_story_30540601_74_dialog_content = "¿Eh? ¿Te refieres a esos altavoces de mala calidad usados para los actos de apertura? ¡Ni en un millón de años soñaría con tocarlos!",
  ui_story_30540601_75_dialog_content = "¿Qué fue eso? ¿Estás intentando buscar pelea?!",
  ui_story_30540601_76_dialog_content = "E-Esperen ustedes dos, ¡sólo cálmense! Ambos están perdiendo algunas de sus pertenencias, ¿no es así? ¿Podría ser...",
  ui_story_30540601_77_dialog_content = "¿Crees que te tengo miedo? ¡Resolvamos esto de una vez por todas! ¡Aquí mismo, ahora mismo!",
  ui_story_30540601_78_dialog_content = "Puedes ser el juez, PlayerName!",
  ui_story_30540601_79_dialog_content = "¿¡Por qué sigues luchando!? ¡Me niego a tener parte en esto...!",
  ui_story_30540601_80_dialog_content = "¡Entonces permítame actuar como el juez!",
  ui_story_30540601_81_dialog_content = "¿Eh? Esa voz... ¿No es...?",
  ui_story_30540601_82_dialog_content = "¡Primero! ¡Actúa como un faro para guiar a otros hacia adelante!",
  ui_story_30540601_83_dialog_content = "¡Segundo! ¡Asegúrate de que el uniforme esté planchado y las arrugas estén bien marcadas!",
  ui_story_30540601_84_dialog_content = "¡Tercero! ¡Mantén una ética de trabajo diligente en todo momento!",
  ui_story_30540601_85_dialog_content = "\"<color=#FFB400>Capitán de Patrulla</color>\" Nadine está aquí para cumplir con sus deberes y presidir este enfrentamiento crucial!",
  ui_story_30540601_86_dialog_content = "... Hay tantas cosas mal en esta situación que no sé ni por dónde empezar.",
  ui_story_30540601_87_dialog_content = "De todos modos, ¿podrías explicar de qué se trataba esa introducción?",
  ui_story_30540601_88_dialog_content = "Bueno, una de las reglas en el manual de Vice es \"preservar un sentido de amor y armonía a bordo del Colossus\"...",
  ui_story_30540601_89_dialog_content = "¿Qué tiene que ver eso con tu loca introducción de hace un momento?!",
  ui_story_30540601_90_dialog_content = "El manual también indica que \"al mediar entre dos partes en conflicto, recuerde presentarse como mediador ante ambos lados.\"",
  ui_story_30540601_91_dialog_content = "Estoy bastante seguro de que por \"mediar\", el manual se refiere a \"detener la pelea\"...",
  ui_story_30540601_92_dialog_content = "...",
  ui_story_30540601_93_dialog_content = "Mira, PlayerName! Están tan sorprendidos que se han olvidado por completo de su discusión...",
  ui_story_30540601_94_dialog_content = "Eso debe contar como detener su pelea de alguna manera, ¿verdad?",
  ui_story_30540601_95_dialog_content = "... De todos modos, cuando dijiste que estabas inspeccionando habitaciones antes...",
  ui_story_30540601_96_dialog_content = "¿Por casualidad confiscaste los altavoces de Regina y la sierra de Barbara mientras lo hacías?",
  ui_story_30540601_97_dialog_content = "De hecho, quité dos altavoces grandes del salón anteriormente.",
  ui_story_30540601_98_dialog_content = "Además de una sierra, que encontré en la esquina del Café.",
  ui_story_30540601_99_dialog_content = "¡No lo olvidé allí! Solo lo dejé por un ratito.",
  ui_story_30540601_100_dialog_content = "¿Eh? ¿Qué te da el derecho de tomar mis altavoces?!",
  ui_story_30540601_101_dialog_content = "¡Las extrañas tuberías que sobresalen de ellos lanzan llamas! ¡Son demasiado peligrosas!",
  ui_story_30540601_102_dialog_content = "¡Pero eso es parte de mi acto! ¡Son efectos especiales!",
  ui_story_30540601_103_dialog_content = "Espera, según la regla en el manual... ¡Tu peinado también es increíblemente peligroso!",
  ui_story_30540601_104_dialog_content = "¿¡Qué clase de regla es esa!?",
  ui_story_30540601_105_dialog_content = "Cuando subí por primera vez al Colossus, ¡nadie me mencionó ninguna regla! ¿Por qué mencionarlas ahora, de repente?!",
  ui_story_30540601_106_dialog_content = "¡P-Por favor, dejen de pelear! De todos modos...",
  ui_story_30540601_107_dialog_content = "Nadine, ¿podrías devolverles su altavoz y sierra primero, por favor?",
  ui_story_30540601_108_dialog_content = "Pero las reglas claramente indican...",
  ui_story_30540601_109_dialog_content = "Estas reglas nunca han sido aplicadas oficialmente en el Colossus antes.",
  ui_story_30540601_110_dialog_content = "¿Eso significa... que cometí un error?",
  ui_story_30540601_111_dialog_content = "¡Para nada! Es solo que las reglas deben ajustarse un poco según la situación. No tienes que seguirlas tan de cerca.",
  ui_story_30540601_112_dialog_content = "Muy bien. Después de todo, eres el Navegante.",
  ui_story_30540601_113_dialog_content = "Si tú lo dices, seguiré tus órdenes naturalmente...",
  ui_story_30540601_114_dialog_content = "¿Dónde está nuestras cosas? Entrégalo y dejaremos todo esto atrás.",
  ui_story_30540601_115_dialog_content = "Por favor, ven conmigo. Te llevaré allí.",
  ui_story_30540601_116_dialog_content = "PlayerName... Empeoré las cosas, ¿verdad?",
  ui_story_30540601_117_dialog_content = "*Ejem* No te castigues por eso.",
  ui_story_30540601_118_dialog_content = "Seguir las reglas de manera tan cercana y fiel como lo hiciste también es digno de elogio.",
  ui_story_30540601_119_dialog_content = "Las cosas simplemente se salieron un poco de control, eso es todo.",
  ui_story_30540601_120_dialog_content = "No hace falta decir que creo que deberíamos evitar confiscar las cosas de alguien de ahora en adelante.",
  ui_story_30540601_121_dialog_content = "Todos a bordo del Colossus se preocupan por los demás y nunca harían algo que pusiera en peligro las vidas de los demás, relativamente...",
  ui_story_30540601_122_dialog_content = "Muy bien, ¡ahora entiendo!",
  ui_story_30540601_123_dialog_content = "¡Oh! Seguro que debes tener sed después de toda esa explicación.",
  ui_story_30540601_124_dialog_content = "¿Te gustaría algo para beber? Puedo preparar casi cualquier cosa, especialmente té y café.",
  ui_story_30540601_125_dialog_content = "No gracias, estoy bien.",
  ui_story_30540601_125X1_dialog_content = "Pero siento que debo hacer algo como disculpa... ¿Te gustaría un masaje en los hombros entonces?",
  ui_story_30540601_126_dialog_content = "Eh... T-Tal vez una taza de café no estaría mal... Con leche extra y azúcar, por favor!",
  ui_story_30540601_127_dialog_content = "¡No hay problema! ¡Volveré con tu café antes de que te des cuenta!",
  ui_story_30540601_128_dialog_content = "Regresé, PlayerName—",
  ui_story_30540601_129_dialog_content = "\"¡Amo trabajar, sí lo hago!\"",
  ui_story_30540601_130_dialog_content = "¡Ahhh!!",
  ui_story_30540601_131_dialog_content = "N-Nadine, ¿estás bien?!",
  ui_story_30540601_132_dialog_content = "Yo... estoy bien... Pero tu café, yo...",
  ui_story_30540601_133_dialog_content = "¡Eso no es importante! ¿Te duele en alguna parte?",
  ui_story_30540601_134_dialog_content = "No, pero... Mi ropa nueva...",
  ui_story_30540601_135_dialog_content = "¡Lo siento! ¡Iré a lavarlos ahora mismo!",
  ui_story_30540601_136_dialog_content = "Está bien, solo afectó una pequeña parte... *Suspiro* Ella ya se fue.",
  ui_story_30540601_137_dialog_content = "Urgh...",
  ui_story_30540601_138_dialog_content = "Está bien, Nadine. El café solo se derramó en una pequeña parte de la ropa.",
  ui_story_30540601_139_dialog_content = "Pero... Pero prometí que no ensuciaría este!",
  ui_story_30540601_140_dialog_content = "Y también fallé completamente en el <color=#FFB400>deber de patrulla</color>...",
  ui_story_30540601_141_dialog_content = "Fueron solo pequeños errores, Nadine! Es perfectamente normal encontrarse con pequeños problemas como este.",
  ui_story_30540601_142_dialog_content = "Además, verte caer y derramar bebidas sobre ti mismo... Ya me he acostumbrado, al menos.",
  ui_story_30540601_143_dialog_content = "¡¿Eh?! ¿E-Estoy... realmente tan torpe...?",
  ui_story_30540601_144_dialog_content = "¡Eso no es lo que quiero decir! Lo que quiero decir es que tu torpeza ocasional es uno de tus encantadores rasgos.",
  ui_story_30540601_145_dialog_content = "En cualquier caso, no necesitas preocuparte por eso.",
  ui_story_30540601_146_dialog_content = "Cuanto más intentas consolarme... Más siento que he estado defraudando a todos.",
  ui_story_30540601_147_dialog_content = "Pero, ¿por qué? ¡Al fin y al cabo, solo es tu ropa! A menos que... ¿Es eso lo que te molesta? ¿Ensuciar tu ropa?",
  ui_story_30540601_148_dialog_content = "Sí... Un uniforme es extremadamente importante.",
  ui_story_30540601_149_dialog_content = "Para que todos me den un uniforme tan bonito... Deben estar esperando que haga un trabajo aún mejor que antes.",
  ui_story_30540601_150_dialog_content = "¡Para nada! ¿Por qué pensarías eso?",
  ui_story_30540601_151_dialog_content = "Fuerza de costumbre, supongo...",
  ui_story_30540601_152_dialog_content = "*Suspiro* Siempre hablas de trabajo, incluso cuando no estás trabajando...",
  ui_story_30540601_153_dialog_content = "La razón por la que te di esta ropa fue porque pensé que realmente te quedaba bien, ¡eso es todo!",
  ui_story_30540601_154_dialog_content = "Además, pensé que al darte ropa más casual y cómoda...",
  ui_story_30540601_155_dialog_content = "Podrías <color=#FFB400>alejarte del trabajo y descansar</color> un poco más.",
  ui_story_30540601_156_dialog_content = "No pensé que tomarías el servicio de patrulla tan en serio como tu propio trabajo.",
  ui_story_30540601_157_dialog_content = "Ya veo. Pero este atuendo... ¿Es casual?",
  ui_story_30540601_158_dialog_content = "Uh... De acuerdo, me atrapaste. Yo tampoco estoy del todo seguro de eso...",
  ui_story_30540601_159_dialog_content = "¡Pero mira! Es ligero y transpirable, y no tiene ninguna propiedad defensiva en absoluto.",
  ui_story_30540601_160_dialog_content = "Parece un poco más relajado que tu uniforme habitual, ¿verdad?",
  ui_story_30540601_161_dialog_content = "Yo creo que sí...",
  ui_story_30540601_162_dialog_content = "De todos modos, es genial que seas tan diligente en todo lo que haces, pero también puede causarte mucho estrés innecesario.",
  ui_story_30540601_163_dialog_content = "Estar de turno es trabajo, no me malinterpretes, pero siempre y cuando te reportes regularmente y completes las patrullas a tiempo, eso es suficiente.",
  ui_story_30540601_164_dialog_content = "No hay necesidad de tomárselo tan en serio.",
  ui_story_30540601_165_dialog_content = "Ahora que he vuelto y no tengo nada que hacer, ¿por qué no te muestro cómo manejar el servicio de patrulla de la manera correcta?",
  ui_story_30540601_166_dialog_content = "¡Está bien!",
  ui_story_30540601_167_dialog_content = "¡He vuelto! ¿Pasó algo mientras no estaba, Nadine...?",
  ui_story_30540601_168_dialog_content = "\"¡Amo los descansos, sí, lo hago!\"",
  ui_story_30540601_169_dialog_content = "\"Me encantan los descansos, ¿y a ti?\"",
  ui_story_30540601_170_dialog_content = "¿Por qué las luciérnagas cantan una canción tan extraña? Espera... ¿Están bailando?!",
  ui_story_30540601_171_dialog_content = "¡Bienvenida de nuevo, señorita Vice!",
  ui_story_30540601_172_dialog_content = "Ya que Vice preguntó tan sinceramente...",
  ui_story_30540601_173_dialog_content = "¡Responderemos lo más sinceramente posible!",
  ui_story_30540601_174_dialog_content = "Estamos de patrulla.",
  ui_story_30540601_175_dialog_content = "Y ya que estamos de patrulla...",
  ui_story_30540601_176_dialog_content = "Para mantener un ambiente pacífico y lleno de amor a bordo del Coloso...",
  ui_story_30540601_177_dialog_content = "¡Hemos reprogramado las Luciérnagas para que toquen una nueva canción!",
  ui_story_30540601_178_dialog_content = "¡Uno que ayudará a todos a disfrutar de una sensación de relajación!",
  ui_story_30540601_179_dialog_content = "¡Hagamos nuestro mejor esfuerzo para relajarnos!",
  ui_story_30540601_180_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_30540601_181_dialog_content = "... Hay tantas cosas mal en esta situación que no sé ni por dónde empezar!",
  ui_story_30540602_1_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_30540602_2_dialog_content = "¡Ahhh—Mi linterna se la llevó el viento!",
  ui_story_30540602_3_dialog_content = "Vaya, si tan solo no hubiera escuchado a ese vendedor ambulante. ¿Qué estoy haciendo aquí, jugando en estas pozas de marea?",
  ui_story_30540602_4_dialog_content = "...",
  ui_story_30540602_5_dialog_content = "¡Oye, veo una luz allá! Será mejor ir a echar un vistazo.",
  ui_story_30540602_6_dialog_content = "...",
  ui_story_30540602_7_dialog_content = "Espera, algo en esa chica sosteniendo una linterna parece extrañamente familiar.",
  ui_story_30540602_8_dialog_content = "¡Es Nadine! ¿Qué estás haciendo aquí?",
  ui_story_30540602_9_dialog_content = "¡Navegador! Espera, ¿no debería hacerte yo la misma pregunta?",
  ui_story_30540602_10_dialog_content = "Antes de eso, debes saber—",
  ui_story_30540602_11_dialog_content = "El viento y las olas aquí son realmente fuertes, y no hay muchos lugares seguros para encontrar apoyo.",
  ui_story_30540602_12_dialog_content = "Un paso en falso y podrías terminar en el océano. Deberías regresar tan pronto como puedas.",
  ui_story_30540602_13_dialog_content = "Lo sé, lo sé. Eres tan responsable como siempre, Nadine.",
  ui_story_30540602_14_dialog_content = "Simplemente nunca esperé encontrarte en Twin Pavilions Bay, eso es todo...",
  ui_story_30540602_15_dialog_content = "Y pareces un poco diferente de lo habitual...",
  ui_story_30540602_16_dialog_content = "¿Podrías decirme qué estás haciendo aquí?",
  ui_story_30540602_17_dialog_content = "Eres bastante persistente.",
  ui_story_30540602_18_dialog_content = "... Supongo que podría contarte sobre mi trabajo a tiempo parcial: sostenedor de una linterna.",
  ui_story_30540602_19_dialog_content = "El aspecto más importante de mi trabajo es... esperar.",
  ui_story_30540602_20_dialog_content = "¿Esperando?",
  ui_story_30540602_21_dialog_content = "Sí. ¿Ves el horizonte allá? Probablemente esté demasiado oscuro para verlo claramente ahora mismo.",
  ui_story_30540602_22_dialog_content = "Pero generalmente hay muchos barcos allí. Muchos.",
  ui_story_30540602_23_dialog_content = "Barcos mercantes que viajan de norte a sur, embarcaciones de pesca cargadas de enormes capturas y barcos turísticos llevando a pasajeros emocionados.",
  ui_story_30540602_24_dialog_content = "Mi colega del turno anterior dice que los visitantes suelen recitar poemas mientras aprecian las vistas aquí.",
  ui_story_30540602_25_dialog_content = "Debe ser muy relajante para la mente y el espíritu.",
  ui_story_30540602_26_dialog_content = "Entonces, ¿estás esperando esos barcos?",
  ui_story_30540602_27_dialog_content = "Sí. Mi trabajo es esperar el regreso de cada barco que parte de aquí.",
  ui_story_30540602_28_dialog_content = "Y cuando el clima es especialmente malo, ¡también es mi trabajo iluminar su camino hacia la seguridad!",
  ui_story_30540602_29_dialog_content = "Lo cual es aún más razón por la que deberías volver ahora, Navegante. Es peligroso estar fuera con este clima.",
  ui_story_30540602_30_dialog_content = "Incluso podría estar gestándose una tormenta...",
  ui_story_30540602_31_dialog_content = "¿Por qué no vienes conmigo, Nadine? Si el clima está tan malo, probablemente tampoco deberías estar trabajando.",
  ui_story_30540602_32_dialog_content = "No puedo irme. Aún no.",
  ui_story_30540602_33_dialog_content = "Todavía estoy esperando algo...",
  ui_story_30540602_34_dialog_content = "¿Esperando qué?",
  ui_story_30540602_35_dialog_content = "Por los sonidos de esos barcos regresando al puerto.",
  ui_story_30540602_36_dialog_content = "... ¿Alguna vez has experimentado algo así, Navegante?",
  ui_story_30540602_37_dialog_content = "Cuando pasas un día entero en un estado de concentración total, empiezas a notar todo tipo de sonidos.",
  ui_story_30540602_38_dialog_content = "¿Te gusta escuchar a los pájaros volar entre las nubes?",
  ui_story_30540602_39_dialog_content = "Sí, algo así.",
  ui_story_30540602_40_dialog_content = "Cuando trabajo en este arrecife, viendo todos esos barcos ir y venir...",
  ui_story_30540602_41_dialog_content = "Las olas me traen historias de los barcos en el mar.",
  ui_story_30540602_42_dialog_content = "Eso es bastante inusual...",
  ui_story_30540602_43_dialog_content = "Una vez, escuché sobre cómo un barco de pesca volcó y su tripulación fue arrojada al mar.",
  ui_story_30540602_44_dialog_content = "Afortunadamente, un bote de rescate cercano apareció y sacó a todos del agua.",
  ui_story_30540602_45_dialog_content = "Cuando los pescadores finalmente llegaron a tierra, sus esposas reaccionaron de diversas maneras.",
  ui_story_30540602_46_dialog_content = "Algunas de ellas abrazaron a sus esposos y lloraron, mientras que otras los llevaron a casa tirándoles de la oreja.",
  ui_story_30540602_47_dialog_content = "Ya veo... Historias como esas son como las nubes: vienen en todas las formas y tamaños.",
  ui_story_30540602_48_dialog_content = "Pueden contarte mucho sobre el mundo que nos rodea y qué tan rápido pueden cambiar las cosas.",
  ui_story_30540602_49_dialog_content = "En efecto... Bueno, el viento se está haciendo más fuerte. Debe haber una tormenta furiosa en marcha ahora.",
  ui_story_30540602_50_dialog_content = "¿Seguro que no quieres volver? Todavía hay tiempo, ya sabes...",
  ui_story_30540602_51_dialog_content = "Estaré bien. ¡Cuéntame otra historia que hayas escuchado del mar!",
  ui_story_30540602_52_dialog_content = "¡Nos ayudará a pasar el tiempo!",
  ui_story_30540602_53_dialog_content = "Las historias del océano son casi todas iguales. No creo que a la gente realmente le interese escucharlas.",
  ui_story_30540602_54_dialog_content = "¿Por qué no te cuento una historia que me contó alguien más? Mi colega, para ser precisos.",
  ui_story_30540602_55_dialog_content = "En las costas de una tierra lejana, hay una torre de piedra con forma de loto.",
  ui_story_30540602_56_dialog_content = "Al pie de esta torre hay innumerables leones pequeños que también están hechos de piedra.",
  ui_story_30540602_57_dialog_content = "Esta torre distante no es especialmente alta ni hermosa. Tampoco emite un resplandor dorado.",
  ui_story_30540602_58_dialog_content = "Sin embargo, ocupa un lugar especial en el corazón de quienes viven cerca. Siempre que sufre daños, alguien inevitablemente lo arreglará.",
  ui_story_30540602_59_dialog_content = "Hasta el día de hoy, se yergue orgullosa al borde del mar. A lo largo de los años, las personas se han parado en lo alto de la torre con faroles en la mano, igual que yo...",
  ui_story_30540602_60_dialog_content = "Guiando a barcos extraviados hacia la seguridad durante incontables siglos.",
  ui_story_30540602_61_dialog_content = "... Siempre me ha gustado esta historia, principalmente porque también llevo una linterna a dondequiera que voy.",
  ui_story_30540602_62_dialog_content = "Quiero seguir iluminando el camino para los demás, aunque sea solo un poco más de tiempo.",
  ui_story_30540602_63_dialog_content = "... El viento se está poniendo aún peor, Navegador... ¿Podrás mantenerte en pie?",
  ui_story_30540602_64_dialog_content = "Estaré bien.",
  ui_story_30540602_65_dialog_content = "Entonces te sugiero que encuentres un lugar más seguro. Una vez que comience a llover, podría no ser capaz de salvarte.",
  ui_story_30540602_66_dialog_content = "No te preocupes, pensaré en algo si las cosas realmente empeoran.",
  ui_story_30540602_67_dialog_content = "Si ya terminaste con tu historia, me gustaría compartir una mía.",
  ui_story_30540602_68_dialog_content = "Una vez, había un viajero que llegó a las costas de la Bahía de los Pabellones Gemelos. Mientras observaba las pozas de marea, conoció a una joven de Lumopolis.",
  ui_story_30540602_69_dialog_content = "Ella iba vestida a la moda de Twin Pavilions Bay. Mientras caminaba por la orilla del mar, sostenía una linterna en sus manos.",
  ui_story_30540602_70_dialog_content = "Se acercaba una tormenta, pero ella se negó a abandonar su puesto en lo alto de un gran arrecife.",
  ui_story_30540602_71_dialog_content = "Escuchó las olas mientras esperaba que los barcos regresaran a casa.",
  ui_story_30540602_72_dialog_content = "No había faros aquí, lo que hacía que sus deberes fueran especialmente importantes ante la tormenta que se avecinaba; ella es una protectora.",
  ui_story_30540602_73_dialog_content = "¡No solo protegía a los barcos en el mar, sino también a cualquier buscador de pozas de marea perdido que apareciera en la playa!",
  ui_story_30540602_74_dialog_content = "Eres tú...",
  ui_story_30540602_75_dialog_content = "¿Me estás felicitando ahora mismo?",
  ui_story_30540602_76_dialog_content = "¡No creo que nadie haya reconocido mi trabajo así antes!",
  ui_story_30540602_77_dialog_content = "Estoy bastante seguro de que todos sienten eso sobre tu trabajo, incluso si no lo dicen.",
  ui_story_30540602_78_dialog_content = "Escuchando a los barcos ir y venir e iluminando su camino a casa...",
  ui_story_30540602_79_dialog_content = "¡Eres tan importante como un faro en sus ojos!",
  ui_story_30540602_80_dialog_content = "La lluvia está empezando a caer.",
  ui_story_30540602_81_dialog_content = "¿Estás completamente seguro de que no quieres regresar, Navegador?",
  ui_story_30540602_82_option_content = "¿Realmente tienes que preguntar?",
  ui_story_30540602_83_option_content = "No puedo dejar el faro desatendido, ¿verdad?",
  ui_story_30540602_84_dialog_content = "Navegador... Gracias.",
  ui_story_30540602_85_dialog_content = "Quiero intentar algo.",
  ui_story_30540602_86_dialog_content = "Usar mi poder para ayudar a tantas personas como sea posible, ¡incluso si es solo un bañista perdido!",
  ui_story_30540602_87_dialog_content = "Luz... reúnete ahora.",
  ui_story_30540602_88_dialog_content = "¡Bajo la linterna!",
  ui_story_30540602_89_dialog_content = "Los cielos se están despejando.",
  ui_story_30540602_90_dialog_content = "¡Achu! Uf, creo que podría haber cogido un resfriado.",
  ui_story_30540602_91_dialog_content = "Tiene sentido, ya que estuvimos afuera bajo la lluvia intensa durante tanto tiempo.",
  ui_story_30540602_92_dialog_content = "Aun así, debemos haber ayudado a algunas personas que estaban atrapadas en el mar, ¿verdad?",
  ui_story_30540602_93_dialog_content = "Estoy seguro de que sí. Después de todo, el mar se ve mucho menos triste ahora.",
  ui_story_30540602_94_dialog_content = "El mar está vivo. Eso es algo que siempre recordaré cuando se vea triste.",
  ui_story_30540602_95_dialog_content = "Por eso quiero elevar mi linterna aún más alto. Tan alto como un faro.",
  ui_story_30540602_96_dialog_content = "Puedes hacerlo, Nadine! ¿Entonces podemos regresar ya?",
  ui_story_30540602_97_dialog_content = "Sí. Una vez que volvamos a la ciudad, me pondré ropa seca y tomaré una buena y larga siesta...",
  ui_story_30540602_98_dialog_content = "¡Espera! ¡Todavía tengo que presentarme a trabajar hoy!",
  ui_story_30540602_99_dialog_content = "Oh no, ¿qué hora es...?",
  ui_story_30540602_100_dialog_content = "¿Eh? ¿Quieres decir que estás haciendo esto además de tu trabajo habitual en Lumopolis?!",
  ui_story_30540602_101_dialog_content = "¡Eso es demasiado, incluso para ti! ¡Deberías llamar para decir que estás enfermo!",
  ui_story_30540602_102_dialog_content = "¡No puedo! El trabajo es trabajo. Cancelar sería igual que eludir mis deberes. Tengo que... ¡Achoo!",
  ui_story_30540602_103_dialog_content = "¡Achu! ¡Achu! ¡Achu!",
  ui_story_30540602_104_dialog_content = "Vuelve y descansa ahora mismo, Nadine!",
  ui_story_30540602_105_dialog_content = "Pero mi trabajo...",
  ui_story_30540602_106_dialog_content = "¡Achuu!"
}
return config
